PROGRAM ST_T03_SAMMANFLODE
VAR
    steg      : INT := 0;
    nastaBana : INT := 1;
    tmrPass   : TON;
    gapOk     : BOOL := FALSE;
END_VAR

(* Luckan framfor sammanflodet maste vara minst 150 mm for att rymma en enhet
   och under 1200 mm (banans langd); annars ar givaren blind (gap_lag och gap_hog). *)
gapOk := (ST030_MRG_GAP >= 150.0) AND (ST030_MRG_GAP < 1200.0);

tmrPass(IN := (steg = 3) AND NOT ST030_PEC_MERGE, PT := T#1500ms);

IF NOT EMG_OK THEN
    ST030_STP1_OPEN := FALSE;
    ST030_STP2_OPEN := FALSE;
    ST030_CNV_RUN   := FALSE;
    steg := 0;
ELSE
    ST030_CNV_RUN := TRUE;

    CASE steg OF
        0:
            ST030_STP1_OPEN := FALSE;
            ST030_STP2_OPEN := FALSE;
            IF NOT ST030_PEC_MERGE AND gapOk THEN
                IF nastaBana = 1 THEN
                    IF ST030_PEC_LANE1 THEN
                        ST030_STP1_OPEN := TRUE;
                        steg := 1;
                    ELSIF ST030_PEC_LANE2 THEN
                        ST030_STP2_OPEN := TRUE;
                        steg := 2;
                    END_IF;
                ELSE
                    IF ST030_PEC_LANE2 THEN
                        ST030_STP2_OPEN := TRUE;
                        steg := 2;
                    ELSIF ST030_PEC_LANE1 THEN
                        ST030_STP1_OPEN := TRUE;
                        steg := 1;
                    END_IF;
                END_IF;
            END_IF;
        1:
            IF ST030_PEC_MERGE THEN
                ST030_STP1_OPEN := FALSE;
                nastaBana := 2;
                steg := 3;
            END_IF;
        2:
            IF ST030_PEC_MERGE THEN
                ST030_STP2_OPEN := FALSE;
                nastaBana := 1;
                steg := 3;
            END_IF;
        3:
            IF tmrPass.Q THEN
                steg := 0;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

